function openDB(){return new Promise((ok,bad)=>{const r=indexedDB.open('poker-ledger-v6-test',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>ok(r.result);r.onerror=()=>bad(r.error)});}
