function mergeView(){const m=getMerge();if(!m)return home();const rec=mergeRecords(m);if(!rec)return panel('合併來源或玩家對應異常',`<p class="warn">來源牌局缺失，或來源牌局新增了尚未對應的玩家。請返回列表檢查並修改玩家對應，避免漏算。</p>${btn('home','返回牌局列表')}`);const names=m.groups.map(g=>g.name),kinds=['mini','cash','reward'],sums=kinds.map(k=>names.map((_,i)=>sum(rec[k].map(r=>r.values[i])))),total=names.map((_,i)=>sum(sums.map(a=>a[i])));const sections=kinds.map((k,ki)=>{const rows=names.map((n,i)=>[n,...rec[k].map(r=>r.values[i]),sums[ki][i]]);rows.push(['合計',...rec[k].map(r=>sum(r.values)),sum(sums[ki])]);return `<details class="ledger-fold"><summary><span>${['區塊一｜小遊戲結算','區塊二｜現金桌紀錄','區塊三｜額外獎勵'][ki]}</span><span class="ledger-count">${rec[k].length} 筆 ▾</span></summary><div class="ledger-fold-content"><p class="sub">${rec[k].map((r,i)=>`第 ${i+1} 筆：${esc(r.source)} 原第 ${r.entryIndex} 筆${r.sub>1?'（子項 '+r.sub+'）':''} · ${r.time===null?'時間不明':new Date(r.time).toLocaleString('zh-TW')}`).join('<br>')||'無紀錄'}</p>${table(['玩家',...rec[k].map((_,i)=>'第 '+(i+1)+' 筆'),'累計'],rows)}</div></details>`}).join('');const grand=table(['玩家','小遊戲累計盈虧','現金桌累計盈虧','額外獎勵盈虧','總籌碼盈虧','現金換算'],names.map((n,i)=>[n,...sums.map(a=>a[i]),total[i],`<span class="${color(money(total[i]))}">${fmt(money(total[i]))} 元</span>`]).concat([['合計',...sums.map(a=>sum(a)),sum(total),`<span class="${color(sum(total.map(money)))}">${fmt(sum(total.map(money)))} 元</span>`]]));const detail=table(['玩家',...mergeSources(m).map(s=>s.title),'合計'],names.map((n,i)=>[n,...m.sourceIds.map(id=>sum(kinds.flatMap(k=>rec[k].filter(r=>r.sourceId===id).map(r=>r.values[i])))),total[i]]).concat([['合計',...m.sourceIds.map(id=>sum(kinds.flatMap(k=>rec[k].filter(r=>r.sourceId===id).flatMap(r=>r.values)))),sum(total)]]));return panel(esc(mergeTitle(m)),`<p class="sub">${m.sourceIds.length} 場來源牌局 · 自動同步 · 唯讀${m.note?' · 備註：'+esc(m.note):''}</p>${btn('home','返回牌局列表')}${sections}${panel('總帳',grand)}<details class="ledger-fold"><summary>來源牌局盈虧明細 ▾</summary><div class="ledger-fold-content">${detail}</div></details>`);}
function mergeChange(t){if(t.dataset.mergeSource!==undefined){mergeSelected=t.checked?[...new Set([...mergeSelected,t.dataset.mergeSource])]:mergeSelected.filter(x=>x!==t.dataset.mergeSource);return true;}if(t.dataset.mergeMap!==undefined&&mergeDraft){const key=t.dataset.mergeMap;if(t.value==='__new__'){const name=prompt('請輸入新的合併玩家名稱',mergePlayerKeys(mergeDraft).find(x=>x.key===key)?.name||'');if(!name?.trim()){render();return true;}const id=uid();mergeDraft.groups.push({id,name:name.trim()});mergeDraft.mapping[key]=id;}else mergeDraft.mapping[key]=t.value;render();return true;}return false;}
async function mergeAction(a){if(a==='merge-start'){if(state.sessions.length<2){alert('至少需要兩場牌局才能合併。');return true;}mergeSelected=[];screen='merge-select';render();return true;}if(a==='merge-next'){if(mergeSelected.length<2){alert('請至少選取兩場牌局。');return true;}const groups=[],mapping={};for(const id of mergeSelected){const s=state.sessions.find(x=>x.id===id);for(const p of s.players){let g=groups.find(x=>x.name===p.name&&!s.players.some(other=>other.id!==p.id&&mapping[s.id+'|'+other.id]===x.id));if(!g){g={id:uid(),name:p.name};groups.push(g);}mapping[s.id+'|'+p.id]=g.id;}}mergeDraft={sourceIds:[...mergeSelected],groups,mapping,note:''};mergeEditing=false;screen='merge-map';render();return true;}if(a.startsWith('merge-open:')){mergeCurrent=a.slice(11);screen='merge-view';render();return true;}if(a.startsWith('merge-edit:')){mergeCurrent=a.slice(11);const m=getMerge();if(!m)return true;mergeDraft=structuredClone(m);mergeEditing=true;screen='merge-map';render();return true;}if(a==='merge-save'){if(!mergeDraft)return true;const keys=mergePlayerKeys(mergeDraft),groups=new Map(mergeDraft.groups.map(g=>[g.id,g]));if(keys.some(x=>!groups.has(mergeDraft.mapping[x.key]))){alert('請完成所有玩家對應。');return true;}for(const sid of mergeDraft.sourceIds){const ids=keys.filter(x=>x.session.id===sid).map(x=>mergeDraft.mapping[x.key]);if(new Set(ids).size!==ids.length){alert('同一場牌局的不同玩家不可對應到同一人。');return true;}}mergeDraft.groups=mergeDraft.groups.filter(g=>keys.some(x=>mergeDraft.mapping[x.key]===g.id));if(mergeEditing){const i=state.merges.findIndex(m=>m.id===mergeCurrent);if(i>=0)state.merges[i]=mergeDraft;}else{mergeDraft.id=uid();state.merges.push(mergeDraft);mergeCurrent=mergeDraft.id;}await save();mergeDraft=null;screen='merge-view';render();return true;}if(a==='merge-cancel'){mergeDraft=null;screen='home';render();return true;}if(a.startsWith('merge-note:')){const m=state.merges.find(x=>x.id===a.slice(11));if(m){const note=prompt('合併表單備註（可留空）',m.note||'');if(note!==null){m.note=note.trim();await save();render();}}return true;}if(a.startsWith('merge-delete:')){const id=a.slice(13),m=state.merges.find(x=>x.id===id);if(m&&confirm('確定刪除「'+mergeTitle(m)+'」？\n只會刪除合併表單及對應設定，不影響原始牌局。')){state.merges=state.merges.filter(x=>x.id!==id);await save();render();}return true;}return false;}

function sessionView(s){
 const extra=rewardCumulative(s),c=cumulative(s),names=s.players.map(p=>p.name);
 const minis=s.entries.filter(e=>e.kind==='mini'||e.kind==='between'||(e.kind==='round'&&(e.games||[]).length));
 const cashEntries=s.entries.filter(e=>e.kind==='cash'||e.kind==='round');
 const rewardEntries=s.entries.filter(e=>e.kind==='reward'||(e.kind==='round'&&(e.rewards||[]).length));
 const miniCount=minis.reduce((n,e)=>n+(e.games?.length||0),0);
 const miniSum=s.players.map((p,i)=>sum(minis.map(e=>projected(s,e,'side')[i])));
 const cashSum=names.map((_,i)=>c.cash[i]-extra[i]);
 // Each confirmed game / cash entry / reward item is one visible column.
 // Values are projected by immutable player ID, so roster edits do not shift history.
 const miniRecords=[];
 for(const e of minis){
  if((e.games||[]).length){for(const g of e.games){miniRecords.push({id:e.id,values:s.players.map(p=>{const j=e.playerIds.indexOf(p.id);return j<0?0:Number(g.deltas?.[j]||0);})});}}
  else if(e.side?.length){miniRecords.push({id:e.id,values:projected(s,e,'side')});}
 }
 const cashRecords=cashEntries.map(e=>({id:e.id,values:s.players.map(p=>{const j=e.playerIds.indexOf(p.id);if(j<0)return 0;
  if(e.kind==='round'){const all=Number(e.cash?.[j]||0),reward=sum((e.rewards||[]).map(r=>Number(r[j]||0)));return all-reward;}
  return Number(e.cash?.[j]||0);
 })}));
 const rewardRecords=[];
 for(const e of rewardEntries){
  if((e.rewards||[]).length){for(const r of e.rewards){rewardRecords.push({id:e.id,values:s.players.map(p=>{const j=e.playerIds.indexOf(p.id);return j<0?0:Number(r[j]||0);})});}}
  else if(e.kind==='reward'){rewardRecords.push({id:e.id,values:s.players.map(p=>{const j=e.playerIds.indexOf(p.id);return j<0?0:Number(e.cash?.[j]||0);})});}
 }
 const overview=(title,desc,records,action)=>{
  const headers=['玩家',...records.map((_,i)=>'第 '+(i+1)+' 筆'),'累計'];
  const rows=names.map((name,i)=>[name,...records.map(r=>r.values[i]),sum(records.map(r=>r.values[i]))]);
  rows.push(['合計',...records.map(r=>sum(r.values)),sum(records.flatMap(r=>r.values))]);
  return `<details class="ledger-fold"><summary><span>${title}</span><span class="ledger-count">${records.length} 筆 <span class="fold-arrow">▾</span></span></summary><div class="ledger-fold-content"><p class="sub">${desc}</p><div class="record-matrix">${table(headers,rows)}</div><div class="toolbar">${btn(action,'查看／修改')}</div></div></details>`;
 };
 const topActions=`<div class="toolbar main-actions">${s.status==='open'?`${btn('new-mini','小遊戲輸入','')}${btn('new-cash','現金桌籌碼輸入','')}${btn('new-reward','額外獎勵輸入','')}`:''}</div><div class="toolbar management-actions">${btn('settings','更改牌局設定')}${btn('history','歷史紀錄')}${btn('home','返回牌局列表')}${s.status==='open'?btn('close','結束整場牌局','danger'):btn('reopen','重新開啟牌局')}</div>`;
 return panel(esc(s.title),`<p class="sub">${active(s).length} 位現役玩家 · ${s.status==='closed'?'已結束':'進行中'}</p><div class="stats"><div class="stat">起始籌碼／人<b>${fmt(startFor(s,roundCount(s)+1))}</b></div><div class="stat">全桌籌碼<b>${fmt(active(s).length*startFor(s,roundCount(s)+1))}</b></div><div class="stat">盲注<b>10／20</b></div></div>${topActions}${overview('區塊一｜小遊戲結算','逐筆盈虧及累計；表格可左右滑動，查看／修改可進入每筆紀錄。',miniRecords,'mini-history')}${overview('區塊二｜現金桌紀錄','每筆獨立以開局設定的起始籌碼結算；表格可左右滑動。',cashRecords,'cash-history')}${overview('區塊三｜額外獎勵','逐筆盈虧及累計；表格可左右滑動。',rewardRecords,'reward-history')}${panel('總帳',table(['玩家','小遊戲累計盈虧','現金桌累計盈虧','額外獎勵盈虧','總籌碼盈虧','現金換算'],names.map((name,i)=>[name,c.side[i],c.cash[i]-extra[i],extra[i],c.total[i],`<span class="${color(c.money[i])}">${fmt(c.money[i])} 元</span>`]).concat([['合計',sum(c.side),sum(c.cash)-sum(extra),sum(extra),sum(c.total),`<span class="${color(sum(c.money))}">${fmt(sum(c.money))} 元</span>`]])))}`);
}
function settingsView(s){const count=roundCount(s);return panel('修改牌局｜'+esc(s.title),`<p class="warn">修改玩家僅影響後續局數，歷史玩家使用固定 ID 保留。已結算局數的起始籌碼可指定修改範圍，若驗證不符將拒絕儲存。</p>${field('牌局名稱',editTitle,'edit-title')}${field('未來局數每人起始籌碼',editStart,'edit-start','number')}${playerEditor(editNames,'edit')}<h3>已結算局數的起始籌碼調整</h3><p class="sub">修改歷史起始籌碼會影響該局的籌碼總額驗證，不能讓結尾籌碼總額失衡。</p><div class="field"><label>生效範圍</label><select data-path="edit-scope"><option value="future" ${editScope==='future'?'selected':''}>只影響下一局及之後</option><option value="one" ${editScope==='one'?'selected':''}>指定單局</option><option value="from" ${editScope==='from'?'selected':''}>從指定局數開始（含已結算局）</option></select></div>${editScope!=='future'?`<div class="grid">${field('指定起始局數',editFrom,'edit-from','number')}${field('新的每人起始籌碼',editRound,'edit-round','number')}</div>`:''}<div class="toolbar">${btn('save-settings','確認修改牌局','')}${btn('session','取消')}</div>${count?`<p class="sub">已結算 ${count} 局。若要修正結尾籌碼，請至「歷史紀錄」選擇該局。</p>`:''}`);}
function independentInput(s){const old=editing?s.entries.find(e=>e.id===editing):null,ids=old?old.playerIds:activeIds(s),names=nameList(s,ids),n=ids.length,start=old&&mode==='cash'?Number(entryStart):old?old.startChips:startFor(s,roundCount(s)+1);if(mode==='mini'){const games=form.games.map(g=>calcGame(g,n)),ready=form.games.length>0&&games.every((g,i)=>g.valid&&form.games[i].confirmed);return panel('小遊戲輸入｜終極德州撲克',`<p class="sub">已輸入 ${form.games.length} 筆。${old?'修改歷史紀錄':'每次確認會獨立記錄，不需要現金桌資料。'}</p>${form.games.map((g,i)=>ultimateSummary(g,i,games[i],names)).join('')}${form.games.every(g=>g.confirmed)?btn('add-ultimate','＋ 新增終極德州撲克','full'):''}<div class="toolbar">${btn('confirm-independent',old?'儲存修改':'確認儲存本次小遊戲','',ready?'':'disabled')}${btn('session','返回牌局')}</div>`);}if(mode==='cash'){const chips=ids.map((_,i)=>form.chips[i]??''),ok=chips.every(whole)&&sum(chips.map(Number))===n*start;return panel('現金桌｜獨立紀錄',`<p class="sub">每人起始籌碼：${fmt(start)}。本筆結束籌碼合計必須為 ${fmt(n*start)}；每筆獨立結算。</p>${old?field('本筆起始籌碼',entryStart,'entry-start','number'):''}<div class="grid">${names.map((name,i)=>field(name,chips[i],`chip:${i}`,'number','結束籌碼')).join('')}</div><div class="note">目前合計：<strong class="${ok?'ok':'bad'}">${fmt(sum(chips.map(x=>Number(x)||0)))} / ${fmt(n*start)}</strong></div><div class="toolbar">${btn('confirm-independent',old?'儲存修改':'確認並記錄本筆現金桌','',ok?'':'disabled')}${btn('session','返回牌局')}</div>`);}const rewards=form.rewards.map(r=>calcReward(r,n)),ready=form.rewards.length>0&&rewards.every((r,i)=>r.valid&&form.rewards[i].confirmed===true);let body=`<p class="sub">每筆額外獎勵合計必須為 0。此紀錄與現金桌分開儲存。</p>`;form.rewards.forEach((r,k)=>{body+=`<div class="item"><h3>額外獎勵第 ${k+1} 筆</h3>`;if(r.confirmed){body+=table(['玩家','盈虧'],names.map((name,i)=>[name,rewards[k].values[i]]).concat([['合計',rewards[k].total]]))+btn('edit-reward:'+k,'修改','secondary small')+btn('delete-reward:'+k,'刪除','danger small');}else{names.forEach((name,i)=>{const sign=r.signs[i]||'plus';body+=`<div class="player"><strong>${esc(name)}</strong><div class="signed-input"><div class="seg sign">${btn('sign:'+k+':'+i+':plus','+',sign==='plus'?'active':'')}${btn('sign:'+k+':'+i+':minus','−',sign==='minus'?'active':'')}</div><input data-path="reward:${k}:${i}" type="number" inputmode="decimal" placeholder="輸入籌碼" value="${esc(r.amounts[i]??'')}"></div></div>`;});body+=`<p class="note">合計 ${fmt(rewards[k].total)}</p>${btn('confirm-reward:'+k,'確認這筆額外獎勵','',rewards[k].valid?'':'disabled')}`;}body+='</div>';});if(form.rewards.every(r=>r.confirmed))body+=btn('add-reward','＋ 新增額外獎勵','full');return panel('額外獎勵｜獨立紀錄',body+`<div class="toolbar">${btn('confirm-independent',old?'儲存修改':'確認儲存額外獎勵','',ready?'':'disabled')}${btn('session','返回牌局')}</div>`);}
function rewardEntryValue(s,e,id){const j=e.playerIds.indexOf(id);if(j<0)return 0;return sum((e.rewards||[]).map(r=>r[j]||0));}
function independentHistory(s,kind){const entries=s.entries.filter(e=>kind==='mini'?e.kind==='mini'||e.kind==='between'||e.kind==='round'&&(e.games||[]).length:kind==='cash'?e.kind==='cash'||e.kind==='round':e.kind==='reward'||e.kind==='round'&&(e.rewards||[]).length);return panel(({mini:'小遊戲',cash:'現金桌',reward:'額外獎勵'})[kind]+'｜逐筆紀錄',`<p class="sub">每筆紀錄可獨立查看／修改。原版歷史局數仍完整保留。</p>${entries.length?entries.map((e,i)=>`<div class="list-entry"><strong>第 ${i+1} 筆 · ${esc(e.date)}</strong><p class="sub">${e.kind==='round'?'舊版第 '+e.round+' 局':e.kind==='between'?'舊版局間小遊戲':'獨立紀錄'}</p>${table(['玩家','本筆盈虧'],s.players.map(p=>[p.name,(kind==='reward'?rewardEntryValue(s,e,p.id):projected(s,e,kind==='mini'?'side':'cash')[s.players.indexOf(p)])]))}<div class="toolbar">${btn('view-entry:'+e.id,'查看結算')}${btn('edit-entry:'+e.id,'查看／修改')}${kind==='reward'&&e.kind==='reward'?btn('delete-reward-entry:'+e.id,'刪除','danger small'):''}</div></div>`).join(''):'<div class="empty">尚無紀錄</div>'}${btn('session','返回牌局')}`);}
