const old=editing? s.entries.find(e=>e.id===editing):null;const ids=old?old.playerIds:activeIds(s),names=nameList(s,ids),start=old&&mode==='round'?Number(entryStart):old?old.startChips:startFor(s,roundCount(s)+1),n=ids.length,ev=evaluate(s,form,mode,ids,start),round=old?.round||roundCount(s)+1;
