function rewardCumulative(s){const out=Array(s.players.length).fill(0);for(const e of s.entries){if(e.kind!=='round'&&e.kind!=='reward')continue;const amounts=Array(e.playerIds.length).fill(0);for(const r of e.rewards||[])r.forEach((v,i)=>amounts[i]+=v);e.playerIds.forEach((id,i)=>{const j=s.players.findIndex(p=>p.id===id);if(j>=0)out[j]+=amounts[i];});}return out;}
